import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { UI_VIEWER_SOURCES } from './lib/ui-source-catalog.mjs';

export function renderUiBundle(sources, readSource) {
  const prefix = 'source';
  return [
    '/* Generated by scripts/build-ui-bundle.mjs. Do not edit manually. */',
    `/* ${prefix}-count: ${sources.length} */`,
    ...sources.flatMap(relativePath => [
      `/* ${prefix}: ${relativePath} */`,
      readSource(relativePath).replace(/\r\n?/g, '\n').trim(),
    ]), '',
  ].join('\n\n');
}

export function buildUiBundles(root, {readSource = relativePath => readFileSync(resolve(root, relativePath), 'utf8')} = {}) {
  return { viewer: renderUiBundle(UI_VIEWER_SOURCES, readSource) };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await import('./generate-build-metadata.mjs');
}
